The callback path was already wrapped in `try/except Exception` — what actually kills the thread silently is everything that wrapper misses: a `BaseException` (`KeyboardInterrupt`, `SystemExit`, `MemoryError`, a `GeneratorExit` from a mis-behaving callback), a `repr()` that raises while building the log message, or a logging handler that blows up. Any of those unwinds `_run`, and since nobody joins the thread you learn about it only when the queue silently stops draining. This version closes those, makes death observable, and drains the backlog on the way out so `join_queue()` can't hang on a dead worker.

```python
"""A worker thread that drains a queue.Queue and hands each item to a callback.

Failure policy:
  * Exception from the callback  -> logged, routed to on_error, worker continues.
  * BaseException                -> recorded, worker exits, backlog released.
  * Failure inside the failure   -> swallowed; nothing may unwind _run silently.
"""

import logging
import queue
import sys
import threading

log = logging.getLogger(__name__)


class _Sentinel:
    """Distinct, printable stop marker. Compared by identity, never by value."""

    def __repr__(self):
        return "<SHUTDOWN>"


SHUTDOWN = _Sentinel()


def _safe_repr(obj):
    """repr() that cannot itself take down the error handler."""
    try:
        return repr(obj)
    except Exception:
        return f"<unreprable {type(obj).__name__} at 0x{id(obj):x}>"


class QueueWorker:
    """Consume items from a queue in a background thread.

    The callback runs on the worker thread, one item at a time. `on_error(item,
    exc)` -- if given -- is called for each failed item; it runs on the worker
    thread and its own exceptions are logged and dropped. `stopped` is set when
    the thread exits for any reason, and `error` holds the BaseException that
    caused an abnormal exit (None on a clean sentinel shutdown).
    """

    def __init__(self, callback, q=None, name="queue-worker", daemon=True,
                 sentinel=SHUTDOWN, on_error=None):
        self.callback = callback
        self.on_error = on_error
        self.queue = q if q is not None else queue.Queue()
        self.sentinel = sentinel
        self.error = None
        self.failures = 0
        self.stopped = threading.Event()
        self._thread = threading.Thread(target=self._run, name=name, daemon=daemon)
        self._started = False
        self._stopping = False
        self._lock = threading.Lock()

    def start(self):
        if self._started:
            raise RuntimeError("worker already started")
        self._started = True
        self._thread.start()
        return self

    def put(self, item, block=True, timeout=None):
        self.queue.put(item, block, timeout)

    def _handle_failure(self, item, exc):
        """Report a failed item. Must never raise -- it runs inside _run's try."""
        self.failures += 1
        try:
            log.error("callback failed for item %s", _safe_repr(item), exc_info=exc)
        except Exception:  # a broken logging handler is not worth dying over
            pass
        if self.on_error is None:
            return
        try:
            self.on_error(item, exc)
        except Exception:
            try:
                log.exception("on_error handler itself failed")
            except Exception:
                pass

    def _run(self):
        try:
            while True:
                item = self.queue.get()
                try:
                    if item is self.sentinel:
                        return
                    self.callback(item)
                except Exception as exc:
                    self._handle_failure(item, exc)
                except BaseException as exc:
                    # KeyboardInterrupt, SystemExit, MemoryError, GeneratorExit:
                    # not recoverable per-item, so exit -- but leave a trace.
                    self.error = exc
                    self._handle_failure(item, exc)
                    return
                finally:
                    self.queue.task_done()
        except BaseException as exc:
            # Raised by queue.get() or task_done() itself -- outside the inner
            # guard. Record rather than vanish.
            self.error = exc
            try:
                log.critical("worker loop died", exc_info=exc)
            except Exception:
                pass
        finally:
            self._release_backlog()
            self.stopped.set()

    def _release_backlog(self):
        """Unblock join_queue() for anything we'll never process."""
        if self.error is None:
            return
        while True:
            try:
                self.queue.get_nowait()
            except queue.Empty:
                return
            except Exception:
                return
            try:
                self.queue.task_done()
            except Exception:
                return

    def join_queue(self, timeout=None):
        """Block until submitted items are processed (or the worker has died)."""
        self.queue.join()
        if self.error is not None:
            raise RuntimeError("worker died") from self.error

    def stop(self, timeout=None, wait=True):
        """Enqueue the sentinel, then optionally join the thread. Idempotent."""
        with self._lock:
            if not self._started:
                return
            already, self._stopping = self._stopping, True
        if not already and not self.stopped.is_set():
            self.queue.put(self.sentinel)
        if wait:
            self._thread.join(timeout)

    @property
    def alive(self):
        return self._started and self._thread.is_alive()

    def __enter__(self):
        return self.start()

    def __exit__(self, *exc):
        self.stop()
        return False


def stop_all(workers, timeout=None):
    """Retire a fan-out pool sharing one queue: one sentinel per consumer."""
    for w in workers:
        w.stop(wait=False)
    for w in workers:
        w.stop(timeout=timeout)


if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)

    def work(n):
        if n == 2:
            raise ValueError("two is unlucky")
        print(f"got {n} -> {n * n}")

    with QueueWorker(work, on_error=lambda i, e: print(f"dropped {i}: {e}")) as w:
        for i in range(5):
            w.put(i)
        w.join_queue()
        print("failures:", w.failures)   # 1, and 0,1,3,4 all still ran
```

Three things worth calling out. `_handle_failure` is written to be total — `_safe_repr` plus nested `try` around both the log call and the `on_error` hook — because an exception raised *inside* the handler would propagate out of the `except` clause and produce exactly the silent death this is meant to fix. The `BaseException` arm is deliberately not "continue": a `MemoryError` or a `Ctrl-C` delivered to this thread means the process is in trouble, so the worker records the cause and leaves rather than spinning on it. And `_release_backlog` matters for anyone calling `join_queue()` — `Queue.join()` waits on the unfinished-task counter, so a dead worker with items still queued would block the caller forever; draining with `task_done()` converts that hang into the `RuntimeError` chained off `self.error`.
